MOD = 10**9 + 7
def nCk(n,k):
    return (factorial(n) / (factorial(k) * factorial(n-k))) % MOD
def edge_count(n):
    return nCk(n-2, 2)
def factorial(n):
    ans = 1
    for i in range(1, n+1):
        ans = (ans * i) % MOD
    return ans
def nCr(n, r):
    return (factorial(n) * pow(factorial(r), MOD - 2, MOD) * pow(factorial(n-r), MOD - 2, MOD)) % MOD
def get_smallest(pairs):
    min_length = float('inf')
    min_node = 1
    for i in range(len(pairs)):
        if pairs[i][0] == pairs[i][1] == 1:
            continue
        if len(pairs[i][0]) < min_length:
            min_length = len(pairs[i][0])
            min_node = pairs[i][0][0]
    return min_node
import math
def solve_testcases():
    for _ in range(int(input())):
        N, M = map(int, input().split())
        A = list(map(int, input().split()))
        pairs = []
        for i in range(2, N+1):
            for j in range(i+1, N+1):
                shortest_path = min([len(path) for path in get_smallest([pair for pair in pairs if pair[0] == [i,j]]).lengths], default=0)
                if shortest_path == A[i-2] and shortest_path != 0:
                    pairs.append([pair for pair in pairs if pair[0] == [i,j]])[0].lengths.append([i,j])
                else:
                    pairs.append([[i,j], [shortest_path]])
        if len(pairs) != M-1:
            print(0)
            continue
        ans = 1
        for i in range(2, N+1):
            if len(pairs[i-2][0]) > 0:
                pairs[i-2][0].append(get_smallest(pairs[i-2]))
            else:
                pairs[i-2][0].append([i])
        for pair in pairs:
            ans *= nCr(len(pair[0]), len(pair[0])-1)
        print(ans)
solve_testcases()
